CREATE TABLE IF NOT EXISTS documents (id VARCHAR(64) PRIMARY KEY, title VARCHAR(500) NOT NULL, content TEXT NOT NULL, source_url TEXT NOT NULL, kind VARCHAR(32) NOT NULL, dataset VARCHAR(200) NOT NULL, license VARCHAR(64) NOT NULL);
CREATE TABLE IF NOT EXISTS comparisons (id CHAR(36) PRIMARY KEY, query_id CHAR(36) NOT NULL, prompt MEDIUMTEXT NOT NULL, answer_a TEXT NOT NULL, answer_b TEXT NOT NULL, model VARCHAR(200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(query_id) REFERENCES queries(id));
CREATE TABLE IF NOT EXISTS preferences (comparison_id CHAR(36) PRIMARY KEY, choice VARCHAR(8) NOT NULL, reviewer VARCHAR(200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(comparison_id) REFERENCES comparisons(id), CHECK(choice IN ('a','b','tie','neither')));
